<?php
namespace Tests\Feature;
use App\Models\User;
use Database\Seeders\DatabaseSeeder;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;
use Tests\TestCase;
class EnrollmentTransitionsTest extends TestCase {
 use RefreshDatabase;
 protected function beforeRefreshingDatabase():void{if(!str_ends_with((string)config('database.connections.mysql.database'),'_test'))throw new \RuntimeException('Dedicated test database required.');}
 protected function setUp():void{parent::setUp();\Carbon\Carbon::setTestNow('2026-10-19 08:00:00');}
 protected function tearDown():void{\Carbon\Carbon::setTestNow();parent::tearDown();}
 private function fixture(string $code='T',bool $current=false):array{if(!DB::table('roles')->exists())$this->seed(DatabaseSeeder::class);$sid=DB::table('schools')->insertGetId(['name'=>'Transition '.$code,'code'=>$code,'status'=>'active','timezone'=>'Asia/Karachi','currency'=>'PKR']);$campus=DB::table('campuses')->insertGetId(['school_id'=>$sid,'name'=>'Main','code'=>'MAIN','status'=>'active']);$owner=User::factory()->create();$mid=DB::table('school_memberships')->insertGetId(['school_id'=>$sid,'user_id'=>$owner->id,'status'=>'active']);DB::table('membership_roles')->insert(['school_id'=>$sid,'membership_id'=>$mid,'role_id'=>DB::table('roles')->where('name','owner')->value('id')]);DB::table('membership_campuses')->insert(['school_id'=>$sid,'membership_id'=>$mid,'campus_id'=>$campus]);$from=$current?'2026-09-01':'2025-09-01';$end=$current?'2027-08-31':'2026-09-30';$next=$current?'2027-09-01':'2026-10-01';$last=$current?'2028-08-31':'2027-09-30';$sourceSession=DB::table('academic_sessions')->insertGetId(['school_id'=>$sid,'name'=>'Source','starts_on'=>$from,'ends_on'=>$end,'status'=>'active']);$targetSession=DB::table('academic_sessions')->insertGetId(['school_id'=>$sid,'name'=>'Target','starts_on'=>$next,'ends_on'=>$last,'status'=>'active']);$class1=DB::table('classes')->insertGetId(['school_id'=>$sid,'name'=>'Class 1','position'=>1]);$class2=DB::table('classes')->insertGetId(['school_id'=>$sid,'name'=>'Class 2','position'=>2]);$sections=[];foreach([[$sourceSession,$class1,'A'],[$sourceSession,$class2,'X'],[$targetSession,$class2,'A'],[$targetSession,$class1,'R']] as [$session,$class,$name])$sections[]=DB::table('sections')->insertGetId(['school_id'=>$sid,'campus_id'=>$campus,'academic_session_id'=>$session,'class_id'=>$class,'name'=>$name,'capacity'=>10]);[$source,$transfer,$target,$repeat]=$sections;$students=[];$enrollments=[];for($i=1;$i<=5;$i++){$student=DB::table('students')->insertGetId(['school_id'=>$sid,'admission_no'=>'TR-'.$i,'first_name'=>'Student '.$i,'admitted_on'=>$from,'status'=>'active']);$students[]=$student;$enrollments[]=DB::table('enrollments')->insertGetId(['school_id'=>$sid,'student_id'=>$student,'section_id'=>$source,'roll_no'=>(string)$i,'starts_on'=>$from,'status'=>'active']);}return compact('sid','campus','owner','mid','sourceSession','targetSession','class1','class2','source','target','transfer','repeat','students','enrollments','next','end','from');}
 private function login(array $f):void{$this->actingAs($f['owner'])->withSession(['school_id'=>$f['sid']]);}
 private function data(array $f,array $decisions=[],bool $transfer=false):array{$items=[];foreach($f['enrollments'] as $i=>$en)$items[]=['source_enrollment_id'=>$en,'decision'=>$decisions[$i]['decision']??'hold','target_section_id'=>$decisions[$i]['target_section_id']??null,'roll_no'=>$decisions[$i]['roll_no']??null,'reason'=>$decisions[$i]['reason']??null];return ['title'=>'Reviewed enrollment plan','kind'=>$transfer?'transfer':'promotion','source_section_id'=>$f['source'],'target_session_id'=>$transfer?$f['sourceSession']:$f['targetSession'],'effective_on'=>$transfer?'2026-10-19':$f['next'],'reason'=>'Reviewed class decisions and fee setup separately','entry_key'=>(string)Str::uuid(),'lock_version'=>0,'items'=>$items];}
 private function draft(array $f,array $rows=[],bool $transfer=false):int{return $this->postJson('/app-api/transitions/batches',$this->data($f,$rows,$transfer))->assertOk()->json('id');}
 private function preview(int $id){return $this->getJson('/app-api/transitions/batches/'.$id.'/preview');}
 private function apply(int $id,?array $p=null){$p??=$this->preview($id)->assertOk()->json();return $this->postJson('/app-api/transitions/batches/'.$id.'/apply',['lock_version'=>$p['batch']['lock_version'],'source_digest'=>$p['source_digest'],'confirm_decisions'=>true,'reviewed_fees'=>true]);}
 public function test_mixed_promotion_repeat_graduation_withdrawal_and_hold_apply_atomically_and_retry_once():void{$f=$this->fixture();$this->login($f);$id=$this->draft($f,[['decision'=>'promote','target_section_id'=>$f['target'],'roll_no'=>'A1'],['decision'=>'repeat','target_section_id'=>$f['repeat'],'reason'=>'Repeat after reviewed assessment'],['decision'=>'graduate','reason'=>'Completed the final school class'],['decision'=>'withdraw','reason'=>'Family requested withdrawal']]);$p=$this->preview($id)->assertOk()->assertJsonPath('can_apply',true)->assertJsonPath('counts.hold',1)->json();$this->assertDatabaseCount('enrollments',5);$this->apply($id,$p)->assertOk();$this->apply($id,$p)->assertOk();$this->assertDatabaseCount('enrollments',7);$this->assertDatabaseCount('enrollment_transition_events',4);$this->assertDatabaseHas('enrollments',['id'=>$f['enrollments'][0],'ends_on'=>'2026-09-30','status'=>'completed']);$this->assertDatabaseHas('students',['id'=>$f['students'][2],'status'=>'graduated']);$this->assertDatabaseHas('students',['id'=>$f['students'][3],'status'=>'withdrawn']);$this->assertDatabaseHas('enrollments',['id'=>$f['enrollments'][4],'ends_on'=>null,'status'=>'active']);$this->getJson('/app-api/transitions/batches/'.$id)->assertJsonPath('batch.snapshot.rows.0.name','Student 1');$this->artisan('database:verify')->assertSuccessful();}
 public function test_all_hold_plan_cannot_be_applied_and_confirmation_checkboxes_are_required():void{$f=$this->fixture();$this->login($f);$id=$this->draft($f);$this->preview($id)->assertJsonPath('can_apply',false);$this->apply($id)->assertUnprocessable();$this->postJson('/app-api/transitions/batches/'.$id.'/apply',['lock_version'=>0,'source_digest'=>str_repeat('a',64)])->assertUnprocessable();$this->assertDatabaseCount('enrollment_transition_events',0);}
 public function test_capacity_exceptions_require_fix_or_hold_and_no_student_is_partially_processed():void{$f=$this->fixture();$this->login($f);DB::table('sections')->where('id',$f['target'])->update(['capacity'=>1]);$rows=[['decision'=>'promote','target_section_id'=>$f['target']],['decision'=>'promote','target_section_id'=>$f['target']]];$id=$this->draft($f,$rows);$this->preview($id)->assertJsonPath('counts.blocked',2);$this->apply($id)->assertUnprocessable();$this->assertDatabaseCount('enrollments',5);$rows[1]=['decision'=>'hold'];$d=$this->data($f,$rows);$this->putJson('/app-api/transitions/batches/'.$id,$d)->assertOk();$this->putJson('/app-api/transitions/batches/'.$id,$d)->assertUnprocessable();$this->apply($id)->assertOk();$this->assertDatabaseCount('enrollments',6);}
 public function test_source_or_destination_changes_invalidate_confirmation_digest():void{$f=$this->fixture();$this->login($f);$id=$this->draft($f,[['decision'=>'promote','target_section_id'=>$f['target']]]);$p=$this->preview($id)->assertOk()->json();DB::table('sections')->where('id',$f['target'])->update(['capacity'=>9]);$this->apply($id,$p)->assertUnprocessable();$this->apply($id)->assertOk();$this->apply($id,array_replace($p,['source_digest'=>str_repeat('a',64)]))->assertUnprocessable();}
 public function test_duplicate_rolls_and_wrong_class_decisions_are_reported_before_apply():void{$f=$this->fixture();$this->login($f);$id=$this->draft($f,[['decision'=>'promote','target_section_id'=>$f['target'],'roll_no'=>'Aa'],['decision'=>'promote','target_section_id'=>$f['target'],'roll_no'=>'aa'],['decision'=>'repeat','target_section_id'=>$f['target'],'reason'=>'Invalid repeat destination']]);$this->preview($id)->assertJsonPath('counts.blocked',3);$this->apply($id)->assertUnprocessable();$this->assertDatabaseCount('enrollments',5);}
 public function test_today_transfer_preserves_history_and_blocks_clipping_attendance_or_results():void{$f=$this->fixture('T',true);$this->login($f);$day=DB::table('attendance_sessions')->insertGetId(['school_id'=>$f['sid'],'section_id'=>$f['source'],'attendance_date'=>'2026-10-19','status'=>'submitted','revision'=>1]);DB::table('attendance_records')->insert(['school_id'=>$f['sid'],'attendance_session_id'=>$day,'enrollment_id'=>$f['enrollments'][0],'status'=>'present']);$id=$this->draft($f,[['decision'=>'transfer','target_section_id'=>$f['transfer'],'reason'=>'Move to the corrected class section']],true);$this->preview($id)->assertJsonPath('counts.blocked',1);$this->apply($id)->assertUnprocessable();DB::table('attendance_sessions')->where('id',$day)->update(['attendance_date'=>'2026-10-18']);$this->apply($id)->assertOk();$this->assertDatabaseHas('enrollments',['id'=>$f['enrollments'][0],'ends_on'=>'2026-10-18']);$roster=app(\App\Services\StudentAttendance::class)->roster($f['sid'],$f['source'],'2026-10-18');$this->assertContains($f['enrollments'][0],$roster->pluck('enrollment_id')->all());$roster=app(\App\Services\StudentAttendance::class)->roster($f['sid'],$f['source'],'2026-10-19');$this->assertNotContains($f['enrollments'][0],$roster->pluck('enrollment_id')->all());$this->assertDatabaseHas('attendance_records',['enrollment_id'=>$f['enrollments'][0],'status'=>'present']);}
 public function test_fees_are_not_moved_cancelled_or_automatically_reassigned():void{$f=$this->fixture();$this->login($f);$invoice=DB::table('invoices')->insertGetId(['school_id'=>$f['sid'],'enrollment_id'=>$f['enrollments'][0],'number'=>'INV-OLD','period'=>'2026-11-01','kind'=>'monthly','installment_no'=>1,'issued_on'=>'2026-09-30','due_on'=>'2026-11-10','status'=>'unpaid','total'=>'1200']);$id=$this->draft($f,[['decision'=>'promote','target_section_id'=>$f['target']]]);$this->preview($id)->assertJsonPath('can_apply',true);$this->apply($id)->assertOk();$this->assertDatabaseHas('invoices',['id'=>$invoice,'enrollment_id'=>$f['enrollments'][0],'total'=>'1200.00','status'=>'unpaid']);$this->assertDatabaseCount('student_fee_assignments',0);$this->assertDatabaseCount('student_concessions',0);}
 public function test_future_plans_stay_drafts_until_the_effective_day():void{$f=$this->fixture('T',true);$this->login($f);$id=$this->draft($f,[['decision'=>'promote','target_section_id'=>$f['target']]]);$this->preview($id)->assertJsonPath('can_apply',false);$this->apply($id)->assertUnprocessable();$this->assertDatabaseCount('enrollments',5);\Carbon\Carbon::setTestNow('2027-09-01 08:00:00');$this->preview($id)->assertJsonPath('can_apply',true);$this->apply($id)->assertOk();}
 public function test_cancelled_and_applied_batches_are_immutable_and_a_source_cannot_be_processed_twice():void{$f=$this->fixture();$this->login($f);$d=$this->data($f,[['decision'=>'promote','target_section_id'=>$f['target']]]);$id=$this->postJson('/app-api/transitions/batches',$d)->assertOk()->json('id');$this->postJson('/app-api/transitions/batches',$d)->assertJsonPath('id',$id);$this->postJson('/app-api/transitions/batches/'.$id.'/cancel',['lock_version'=>0,'reason'=>'Cancel this planning attempt'])->assertOk();$this->putJson('/app-api/transitions/batches/'.$id,$d)->assertUnprocessable();$next=$this->draft($f,[['decision'=>'promote','target_section_id'=>$f['target']]]);$this->apply($next)->assertOk();$again=$this->draft($f,[['decision'=>'promote','target_section_id'=>$f['target']]]);$this->preview($again)->assertJsonPath('can_apply',false);$this->apply($again)->assertUnprocessable();$this->assertDatabaseCount('enrollment_transition_events',1);}
 public function test_school_and_campus_scope_and_role_overrides_are_enforced():void{$f=$this->fixture();$b=$this->fixture('B');$this->login($f);$this->getJson('/app-api/transitions/roster?source_section_id='.$b['source'])->assertNotFound();$this->postJson('/app-api/transitions/batches',$this->data($f,[['decision'=>'promote','target_section_id'=>$b['target']]]))->assertNotFound();$teacher=DB::table('roles')->where('name','teacher')->value('id');DB::table('membership_roles')->where('membership_id',$f['mid'])->update(['role_id'=>$teacher]);$this->getJson('/app-api/transitions/setup')->assertForbidden();$principal=DB::table('roles')->where('name','principal')->value('id');DB::table('membership_roles')->where('membership_id',$f['mid'])->update(['role_id'=>$principal]);DB::table('school_role_permissions')->insert(['school_id'=>$f['sid'],'role_id'=>$principal,'permission_id'=>DB::table('permissions')->where('name','students.transitions')->value('id'),'enabled'=>false]);$this->seed(\Database\Seeders\TransitionAccessSeeder::class);$this->getJson('/app-api/transitions/setup')->assertForbidden();}
 public function test_copy_section_structure_preserves_existing_target_sections_and_does_not_copy_staff_or_fees():void{$f=$this->fixture();$this->login($f);$subject=DB::table('subjects')->insertGetId(['school_id'=>$f['sid'],'name'=>'Math','code'=>'MATH']);DB::table('section_subjects')->insert(['school_id'=>$f['sid'],'section_id'=>$f['source'],'subject_id'=>$subject,'required_for_diary'=>true]);$d=['source_session_id'=>$f['sourceSession'],'target_session_id'=>$f['targetSession'],'campus_ids'=>[$f['campus']],'copy_offerings'=>true];$p=$this->postJson('/app-api/transitions/setup-preview',$d)->assertOk()->json();$this->postJson('/app-api/transitions/copy-sections',$d+['source_digest'=>$p['source_digest']])->assertOk()->assertJsonCount(2,'created_ids');$this->postJson('/app-api/transitions/copy-sections',$d+['source_digest'=>$p['source_digest']])->assertUnprocessable();$p=$this->postJson('/app-api/transitions/setup-preview',$d)->assertOk()->json();$this->postJson('/app-api/transitions/copy-sections',$d+['source_digest'=>$p['source_digest']])->assertJsonCount(0,'created_ids');$this->assertDatabaseCount('teacher_assignments',0);$this->assertDatabaseCount('fee_plans',0);$this->assertDatabaseCount('section_subjects',2);}
 public function test_capacity_uses_peak_concurrent_enrollment_rather_than_sum_of_non_overlapping_history():void{$f=$this->fixture('T',true);$this->login($f);DB::table('sections')->where('id',$f['transfer'])->update(['capacity'=>2]);foreach([['2026-10-19','2026-11-01'],['2026-11-02','2027-08-31']] as $i=>[$start,$end]){$student=DB::table('students')->insertGetId(['school_id'=>$f['sid'],'admission_no'=>'DEST-'.$i,'first_name'=>'Target student','admitted_on'=>$start,'status'=>'active']);DB::table('enrollments')->insert(['school_id'=>$f['sid'],'student_id'=>$student,'section_id'=>$f['transfer'],'starts_on'=>$start,'ends_on'=>$end,'status'=>'active']);}$id=$this->draft($f,[['decision'=>'transfer','target_section_id'=>$f['transfer'],'reason'=>'Review date based classroom capacity']],true);$this->preview($id)->assertJsonPath('capacity.0.existing_peak',1)->assertJsonPath('capacity.0.projected_peak',2)->assertJsonPath('can_apply',true);$this->apply($id)->assertOk();}
 public function test_destination_campus_scope_applies_to_saved_history_and_read_only_grants_cannot_finalize():void {
  $f=$this->fixture();$this->login($f);$campus=DB::table('campuses')->insertGetId(['school_id'=>$f['sid'],'name'=>'Branch','code'=>'BR','status'=>'active']);$target=DB::table('sections')->insertGetId(['school_id'=>$f['sid'],'campus_id'=>$campus,'academic_session_id'=>$f['targetSession'],'class_id'=>$f['class2'],'name'=>'Branch A','capacity'=>10]);$id=$this->draft($f,[['decision'=>'promote','target_section_id'=>$target]]);$principal=DB::table('roles')->where('name','principal')->value('id');DB::table('membership_roles')->where('membership_id',$f['mid'])->update(['role_id'=>$principal]);$this->getJson('/app-api/transitions/batches/'.$id)->assertNotFound();$this->getJson('/app-api/transitions/batches')->assertJsonCount(0,'data');$this->preview($id)->assertNotFound();DB::table('membership_campuses')->insert(['school_id'=>$f['sid'],'membership_id'=>$f['mid'],'campus_id'=>$campus]);foreach(['students.transitions'=>false,'students.transitions_view'=>true] as $name=>$enabled)DB::table('school_role_permissions')->insert(['school_id'=>$f['sid'],'role_id'=>$principal,'permission_id'=>DB::table('permissions')->where('name',$name)->value('id'),'enabled'=>$enabled]);$this->getJson('/app-api/transitions/batches/'.$id)->assertOk()->assertJsonPath('can_manage',false);$p=$this->preview($id)->assertOk()->json();$this->apply($id,$p)->assertForbidden();$this->postJson('/app-api/transitions/batches/'.$id.'/cancel',['lock_version'=>0,'reason'=>'Read only must not cancel'])->assertForbidden();$this->assertDatabaseCount('enrollment_transition_events',0);
 }
 public function test_graduated_student_can_be_readmitted_without_rewriting_graduation_history():void {
  $f=$this->fixture();$this->login($f);$id=$this->draft($f,[['decision'=>'graduate','reason'=>'Completed school education']]);$this->apply($id)->assertOk();$this->getJson('/app-api/students?status=graduated')->assertOk()->assertJsonCount(1,'data');$this->postJson('/app-api/students/'.$f['students'][0].'/enrollment',['action'=>'readmit','section_id'=>$f['target'],'effective_on'=>'2026-10-19','roll_no'=>'READMIT','reason'=>'Returning for an additional academic course'])->assertOk();$this->assertDatabaseHas('students',['id'=>$f['students'][0],'status'=>'active']);$this->assertDatabaseHas('enrollments',['id'=>$f['enrollments'][0],'status'=>'graduated','ends_on'=>$f['end']]);$this->assertDatabaseCount('enrollment_transition_events',1);$this->getJson('/app-api/transitions/batches/'.$id)->assertJsonPath('batch.snapshot.counts.graduate',1);
 }

}
